```typescript
class Circle {
  radius: number;

  constructor(radius: number) {
    this.radius = radius;
  }

  calculatePerimeter(): number {
    return 2 * Math.PI * this.radius;
  }

  calculateArea(): number {
    return Math.PI * Math.pow(this.radius, 2);
  }
}

const circularRoom = new Circle(3); // Create a circle instance for a room with radius 3 meters
const circularRoomPerimeter = circularRoom.calculatePerimeter(); // Calculate the perimeter of the room
const circularRoomArea = circularRoom.calculateArea(); // Calculate the area of the room

console.log(`Circular room: perimeter=${circularRoomPerimeter.toFixed(2)}m, area=${circularRoomArea.toFixed(2)}m²`); // Print the results
```

